class Solution {
  private Node first, last;

  public Node treeToDoublyList(Node root) {
    if (root == null) return null;
    link(root);
    first.left = last;
    last.right = first;
    return first;
  }

  // inorder: link each node after the previous one
  private void link(Node node) {
    if (node == null) return;
    link(node.left);
    if (last == null) first = node;
    else {
      last.right = node;
      node.left = last;
    }
    last = node;
    link(node.right);
  }
}
